"""Detailed explanations with diagrams: LLD questions, part 4."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, UML, STATE, TABLE, CODE

X("notification-lld",
  P("""**What you are building.** One service the rest of the company calls to tell a user something, over **email, SMS or push**, depending on the user's preferences. Messages come from **templates** with placeholders, failed sends are **retried with exponential backoff**, and the same event must never notify a user twice (**idempotency**)."""),
  AN("A post office: you hand over a letter with an envelope ID. The clerk checks the ID against a ledger (already sent? then ignore), fills the template, and passes copies to each delivery van the customer opted into. If a van breaks down, it tries again after 50 ms, then 100 ms, then 200 ms, and finally files the letter under 'undeliverable' (dead-letter queue)."),
  UML("Class diagram", [["NotificationService"], ["Channel", "Template", "User"], ["EmailChannel", "FlakySmsChannel", "PushChannel", "ChannelType"]],
      {"NotificationService": (["channels: EnumMap<ChannelType, Channel>", "prefs: Map<userId, Set<ChannelType>>", "templates: Map<id, Template>", "sentKeys: Set<String>", "maxAttempts: int"], ["setPreferences(user, types)", "addTemplate(t)", "notify(idempotencyKey, user, templateId, params)"]),
       "Channel": ("interface", [], ["type(): ChannelType", "send(user, subject, text)"]), "EmailChannel": ([], ["send(...)"]), "FlakySmsChannel": (["calls (fails first time)"], ["send(...)"]), "PushChannel": ([], ["send(...)"]),
       "Template": ("record", ["id, subject, body"], ["render(params)"]), "User": ("record", ["id, email", "phone, deviceToken"], []), "ChannelType": ("enum", ["EMAIL, SMS, PUSH"], [])},
      [["NotificationService", "Channel", "agg", "by type"], ["NotificationService", "Template", "comp"], ["EmailChannel", "Channel", "impl"], ["FlakySmsChannel", "Channel", "impl"], ["PushChannel", "Channel", "impl"],
       ["NotificationService", "User", "dep"], ["Channel", "ChannelType", "assoc"]],
      "Adding WhatsApp = one new `Channel` class and one enum value. The service depends only on the interface (Strategy + Dependency Inversion)."),
  SEQ("notify(\"ship-42\", Asha, \"ORDER_SHIPPED\") with prefs {SMS, PUSH}", ["Caller", "NotificationService", "Template", "SMS", "Push"],
      [["Caller", "NotificationService", "notify(ship-42, asha, ORDER_SHIPPED, {name, orderId})"], ["NotificationService", "NotificationService", "sentKeys.add(\"ship-42\") → true (new)", "", "A `Set.add` that returns false means we already handled this key: the 4th output line is a duplicate call being ignored."],
       ["NotificationService", "Template", "render({name: Asha, order: 42})", "", "A regex replaces every `{{name}}` / `{{orderId}}` placeholder with the matching parameter."],
       ["NotificationService", "SMS", "send(...) attempt 1", "", "The fake SMS gateway times out the first time."], ["SMS", "NotificationService", "Exception: gateway timeout", "r"],
       ["NotificationService", "NotificationService", "sleep 50 ms (50 × 2^(attempt−1))", "", "Exponential backoff: 50, 100, 200 ms… After `maxAttempts` failures it gives up and logs 'failed permanently → DLQ'."],
       ["NotificationService", "SMS", "send(...) attempt 2 ✔"], ["NotificationService", "Push", "send(...) ✔"]]),
  TABLE("What changes in production", ["In this code", "At scale"],
        [["send synchronously in notify()", "put a message on Kafka/SQS per channel; workers send (see the notification HLD)"], ["sleep between retries", "delayed retry queue; never block a worker thread"],
         ["`sentKeys` in memory", "idempotency keys in Redis/DB with a TTL"], ["user prefs in a map", "preference service + quiet hours + rate limits per user"]]))

X("chess-lld",
  P("""**What you are building.** A two-player chess game: an 8×8 board, every piece's movement rules, turn order, **no move may leave your own king in check**, check detection, and undo. The design question is how to put movement rules in the pieces themselves (polymorphism) instead of a giant switch."""),
  AN("Every piece carries its own rule card. The referee (Game) doesn't know how a knight moves; it asks the knight 'can you go from b8 to c6?'. To check for 'check', the referee asks every enemy piece 'can you reach the king's square?'."),
  UML("Class diagram", [["Game"], ["Board", "Move"], ["Piece"], ["King", "Queen", "Rook", "Bishop", "Knight", "Pawn"]],
      {"Game": (["board: Board", "turn: Color", "history: Deque<Move>", "winner: Color"], ["move(from, to)", "undo()"]),
       "Board": (["g: Piece[8][8]"], ["at(pos) / set(pos, piece)", "standard(): Board", "kingOf(color): Pos", "attacked(pos, byColor): boolean"]),
       "Move": ("record", ["from, to", "moved, captured"], []),
       "Piece": ("abstract", ["color: Color"], ["canMove(board, from, to)  (abstract)", "symbol(): char", "show()"]),
       "King": ([], ["1 square any way"]), "Queen": ([], ["rook OR bishop"]), "Rook": ([], ["straight + clear path"]), "Bishop": ([], ["diagonal + clear path"]),
       "Knight": ([], ["|dr·dc| == 2"]), "Pawn": ([], ["forward 1/2, capture diag"])},
      [["Game", "Board", "comp"], ["Game", "Move", "comp", "history"], ["Board", "Piece", "agg", "0..32"], ["King", "Piece", "inh"], ["Queen", "Piece", "inh"], ["Rook", "Piece", "inh"], ["Bishop", "Piece", "inh"], ["Knight", "Piece", "inh"], ["Pawn", "Piece", "inh"]],
      "The knight rule `dr × dc == 2` is a neat trick: only (1,2) and (2,1) multiply to 2."),
  SEQ("move(\"d1\", \"h5\"): validate, apply, check", ["Player", "Game", "Queen", "Board"],
      [["Player", "Game", "move(d1, h5)"], ["Game", "Board", "at(d1), at(h5)", "", "Must be your own piece; the target must be empty or an enemy."],
       ["Game", "Queen", "canMove(board, d1, h5)", "", "Queen = Rook rule OR Bishop rule; both use `clearPath`, which walks square by square and fails if anything is in between."],
       ["Queen", "Game", "true", "r"], ["Game", "Board", "apply move (tentatively)"],
       ["Game", "Board", "attacked(myKing, by BLACK)?", "", "If my own king is attacked after the move, undo it and throw 'Move leaves king in check' (output line 9)."],
       ["Game", "Game", "history.push(Move); turn = BLACK"], ["Game", "Board", "attacked(blackKing, by WHITE)?", "", "If yes print 'BLACK is in check'. In the demo Qxf7 gives check (the Scholar's-mate pattern); BLACK then tries Ke8–e7, which keeps the king under attack, so it's rejected."]]),
  TABLE("What's simplified (say it!)", ["Rule", "Status"],
        [["castling, en passant, promotion", "not implemented: add as special Move types"], ["checkmate / stalemate", "detect by trying every legal move: if none and in check → mate"],
         ["undo", "Move stores the captured piece, so undo restores the board exactly"], ["game ends", "here when a king is captured; real chess ends at mate"]]))

X("meetingroom-lld",
  P("""**What you are building.** A meeting-room booking system: rooms have capacities; book a room for `[start, end)` only if it's free; find free rooms for a time and group size; cancel. Two hard parts: an **efficient overlap check**, and **no double booking** when many people book at once."""),
  AN("Each room has a diary sorted by start time. To check if 10:30–11:30 is free you only need to look at **one** entry: the last meeting that starts before 11:30. If that meeting ends by 10:30, the slot is free; otherwise it overlaps."),
  KEY("Two intervals [s1, e1) and [s2, e2) overlap **iff s1 < e2 and s2 < e1**. Half-open intervals mean a 10:00–11:00 meeting and an 11:00–12:00 meeting don't clash.", "The overlap rule"),
  UML("Class diagram", [["BookingService"], ["RoomPicker", "RoomCalendar", "Room"], ["SmallestFit", "Booking"]],
      {"BookingService": (["rooms: Map<id, Room>", "cal: Map<roomId, RoomCalendar>", "bookings: Map<id, Booking>"], ["addRoom(r)", "available(s, e, people)", "book(s, e, people, owner)", "cancel(bookingId)"]),
       "RoomCalendar": (["byStart: TreeMap<start, Booking>"], ["synchronized isFree(s, e)", "synchronized tryAdd(b)", "synchronized remove(b)"]),
       "RoomPicker": ("interface", [], ["pick(candidates, people)"]), "SmallestFit": ([], ["smallest room that fits"]),
       "Room": ("record", ["id, capacity"], []), "Booking": ("record", ["id, roomId", "start, end, owner"], [])},
      [["BookingService", "RoomCalendar", "comp", "one per room"], ["BookingService", "RoomPicker", "assoc"], ["SmallestFit", "RoomPicker", "impl"], ["BookingService", "Room", "comp"], ["RoomCalendar", "Booking", "agg"]],
      "Each room has its **own** lock (its calendar), so bookings of different rooms never wait for each other."),
  SEQ("Four teams of 10 book 10:30–11:30 at the same moment", ["team0", "team1", "BookingService", "Board calendar", "Hall calendar"],
      [["team0", "BookingService", "book(10:30, 11:30, 10)"], ["team1", "BookingService", "book(10:30, 11:30, 10)"],
       ["BookingService", "BookingService", "candidates = rooms with capacity ≥ 10 that look free: [Board 12, Hall 50]", "", "Huddle (4) is too small. `available` is only a hint: another thread may take the room right after."],
       ["BookingService", "Board calendar", "tryAdd (team0) → true", "", "SmallestFit picks Board. `tryAdd` re-checks and inserts under the calendar's lock: check-and-insert is atomic."],
       ["BookingService", "Board calendar", "tryAdd (team1) → false", "", "team1 lost the race for Board…"],
       ["BookingService", "Hall calendar", "tryAdd (team1) → true", "", "…so it removes Board from its candidates and tries the next smallest, Hall."],
       NOTE(["team0", "Hall calendar"], "team2 and team3 run out of candidates → 'No room available' (output: none)")]),
  TABLE("isFree(10:30, 11:30) on Huddle, which has asha's 10:00–11:00 booking", ["Step", "Value"],
        [["lowerEntry(11:30): latest booking starting before 11:30", "asha 10:00–11:00"], ["does it end after 10:30?", "11:00 > 10:30 → **overlap**, not free"], ["cost", "O(log n) per room thanks to the TreeMap"]]))

X("carrental-lld",
  P("""**What you are building.** A car rental system: branches hold vehicles of types (hatchback, sedan, SUV); customers search by branch, type and **date range**, reserve, pick up, return (maybe late), and pay per day plus extras (GPS, child seat) plus a late fee."""),
  AN("Each car has a wall calendar of reservations. 'Is this SUV free from 20 to 23 Dec?' means 'does any active reservation on its calendar overlap those days?'. Cancelled and returned reservations are crossed out and don't count."),
  STATE("Reservation life cycle", [["[*]"], ["RESERVED"], ["PICKED_UP", "CANCELLED"], ["RETURNED"]],
        [["[*]", "RESERVED", "reserve()"], ["RESERVED", "PICKED_UP", "pickUp()"], ["RESERVED", "CANCELLED", "cancel()"], ["PICKED_UP", "RETURNED", "giveBack(date) → bill"]],
        "`require(r, expectedState)` guards every transition, e.g. you can't return a car you never picked up."),
  UML("Class diagram", [["RentalService"], ["Pricing", "Reservation", "Vehicle"], ["DailyPricing", "Status", "Type"]],
      {"RentalService": (["vehicles: List<Vehicle>", "res: Map<id, Reservation>"], ["search(branch, type, from, to)", "reserve(branch, type, from, to, extras)", "pickUp(id) / cancel(id)", "giveBack(id, date): bill"]),
       "Reservation": (["id, v: Vehicle", "from, to: LocalDate", "extras: List<String>", "status: Status"], ["overlaps(from, to)"]),
       "Pricing": ("interface", [], ["price(reservation, actualReturn)"]), "DailyPricing": (["perDay by Type", "extra per day", "late fee ₹500/day"], ["price(...)"]),
       "Vehicle": ("record", ["plate, type, branch"], []), "Status": ("enum", ["RESERVED, PICKED_UP,", "RETURNED, CANCELLED"], []), "Type": ("enum", ["HATCHBACK, SEDAN, SUV"], [])},
      [["RentalService", "Reservation", "comp"], ["RentalService", "Vehicle", "agg"], ["RentalService", "Pricing", "assoc"], ["DailyPricing", "Pricing", "impl"], ["Reservation", "Vehicle", "assoc"], ["Reservation", "Status", "assoc"], ["Vehicle", "Type", "assoc"]]),
  TABLE("The real bill: SUV with GPS, booked 20→23 Dec, returned 24 Dec", ["Item", "Computation", "₹"],
        [["booked days", "23 − 20", "3"], ["late days", "24 − 23", "1"], ["daily rate", "SUV 3,500 + GPS 200", "3,700"], ["rental", "(3 + 1) × 3,700", "14,800"], ["late fee", "1 × 500", "500"], ["**total**", "", "**15,300**"]]),
  KEY("The demo had one SUV in Chennai, so a second, overlapping SUV reservation fails with 'No SUV available'. `reserve` is `synchronized`, so search-and-reserve can't double-book under concurrency. In a database you'd use a transaction with `SELECT … FOR UPDATE` on the vehicle, or an exclusion constraint on (vehicle, daterange).", "Avoiding double booking"))

X("stackoverflow-lld",
  P("""**What you are building.** The core of Stack Overflow: users ask questions with tags, answer them, vote (one vote per user per post, changeable), accept an answer, and earn or lose **reputation** according to rules. The subtle part is changing a vote: you must undo the old vote's effect before applying the new one."""),
  AN("Think of reputation like a bank balance and each vote like a transaction. If Meera changes her upvote to a downvote, you don't just add a −2; you first **reverse** the +10 she gave, then apply −2. The net change is −12."),
  UML("Class diagram", [["QAService"], ["ReputationPolicy", "Post", "User"], ["DefaultRep", "Question", "Answer"]],
      {"QAService": (["questions", "byTag: Map<tag, List<Question>>", "rep: ReputationPolicy"], ["ask(user, title, body, tags)", "answer(user, q, body)", "vote(voter, post, +1/−1/0)", "accept(asker, answer)", "byTag(tag)"]),
       "Post": ("abstract", ["id, author, body", "votes: Map<User, Integer>"], ["score()", "upRep() (abstract)"]),
       "Question": (["title, tags", "answers: List<Answer>", "accepted: Answer"], ["upRep() = 5"]), "Answer": (["q: Question"], ["upRep() = 10"]),
       "User": (["name", "rep: int"], []), "ReputationPolicy": ("interface", [], ["forVote(post, vote)", "forAccept()"]), "DefaultRep": ([], ["+5 / +10 up, −2 down, +15 accept"])},
      [["QAService", "Question", "comp"], ["QAService", "ReputationPolicy", "assoc"], ["DefaultRep", "ReputationPolicy", "impl"], ["Question", "Post", "inh"], ["Answer", "Post", "inh"], ["Question", "Answer", "comp", "answers"], ["Post", "User", "assoc", "author"]]),
  TABLE("Ravi's reputation in the real demo (his answer)", ["Event", "Change", "Ravi's rep"],
        [["start", "", "1"], ["Meera upvotes the answer", "+10", "11"], ["Asha upvotes the answer", "+10", "21"], ["Meera changes to a downvote", "−10 (undo) − 2 (new)", "9"], ["Asha accepts the answer", "+15", "**24**"]],
        "Asha gets +5 for Meera's upvote on her question (1 + 5 = 6). The answer's score is +1 −1 = 0. Ravi voting on his own answer is rejected."),
  SEQ("vote(meera, answer, −1) after an earlier +1", ["Meera", "QAService", "DefaultRep", "Answer", "Ravi"],
      [["Meera", "QAService", "vote(answer, −1)"], ["QAService", "QAService", "voter ≠ author? ✔", "", "Self-votes throw 'Cannot vote on your own post'."],
       ["QAService", "Answer", "old = votes[meera] = +1"], ["QAService", "DefaultRep", "forVote(answer, −1) − forVote(answer, +1)", "", "−2 − (+10) = −12: one formula handles new votes, changed votes and removed votes (dir 0)."],
       ["QAService", "Ravi", "rep += −12"], ["QAService", "Answer", "votes[meera] = −1"]]),
  KEY("Reputation rules live in `ReputationPolicy` (Strategy), so 'bounties' or 'downvotes cost the voter 1 point' don't touch the service. Storing votes as `Map<User, Integer>` enforces one vote per user per post for free.", "Design point"))
